// 1 when some canonical coefficient of w is at least bound in centered absolute value, else 0.
// func dsaBeyondAVX2(w *[256]uint32, bound uint32) uint32
TEXT ·dsaBeyondAVX2(SB), NOSPLIT, $0-20
	MOVQ	w+0(FP), DI
	LEAQ	dsaMont<>(SB), AX
	VPBROADCASTD	(AX), Y15
	VPBROADCASTD	4(AX), Y14
	MOVL	bound+8(FP), BX
	DECL	BX
	MOVL	BX, X13
	VPBROADCASTD	X13, Y13
	VPXOR	Y0, Y0, Y0
	MOVQ	$32, CX
loop:
	VMOVDQU	(DI), Y1
	VPSUBD	Y1, Y15, Y2
	VPMINUD	Y2, Y1, Y1
	VPCMPGTD	Y13, Y1, Y1
	VPOR	Y1, Y0, Y0
	ADDQ	$32, DI
	DECQ	CX
	JNZ	loop
	XORL	AX, AX
	VPTEST	Y0, Y0
	SETNE	AL
	MOVL	AX, ret+16(FP)
	VZEROUPPER
	RET

