	VPBROADCASTD	8(AX), Y12
	VPBROADCASTD	12(AX), Y7
	LEAQ	dsaRound<>(SB), BX
	VPBROADCASTW	0(BX), Y11
	VPBROADCASTW	2(BX), Y10
	VPBROADCASTD	4(BX), Y9
	VPSRLD	$16, Y9, Y8
	VPSLLD	$16, Y9, Y9
	VPSRLD	$16, Y9, Y9
