// out = the sum of the windows ext[start:start+256] for the first n starts, the start in bits 0-8
// of each entry (at most 256) and the window negated where bit 15 is set.
// func dsaSparseAVX2(out *[256]int16, ext *[512]int16, starts *[64]uint16, n int)
TEXT ·dsaSparseAVX2(SB), NOSPLIT, $0-32
	MOVQ	out+0(FP), DI
	MOVQ	ext+8(FP), SI
	VPXOR	Y0, Y0, Y0
	VPXOR	Y1, Y1, Y1
	VPXOR	Y2, Y2, Y2
	VPXOR	Y3, Y3, Y3
	VPXOR	Y4, Y4, Y4
	VPXOR	Y5, Y5, Y5
	VPXOR	Y6, Y6, Y6
	VPXOR	Y7, Y7, Y7
	MOVQ	starts+16(FP), DX
	MOVQ	n+24(FP), CX
	XORQ	R8, R8
	TESTQ	CX, CX
	JZ	store0
window0:
	MOVWQZX	(DX), AX
	MOVQ	AX, BX
	SHRQ	$15, BX
	ADDQ	BX, R8
	NEGQ	BX
	VMOVQ	BX, X8
	VPBROADCASTQ	X8, Y8
	ANDQ	$0x1ff, AX
	LEAQ	(SI)(AX*2), BX
	VPXOR	0(BX), Y8, Y9
	VPADDW	Y9, Y0, Y0
	VPXOR	32(BX), Y8, Y9
	VPADDW	Y9, Y1, Y1
	VPXOR	64(BX), Y8, Y9
	VPADDW	Y9, Y2, Y2
	VPXOR	96(BX), Y8, Y9
	VPADDW	Y9, Y3, Y3
	VPXOR	128(BX), Y8, Y9
	VPADDW	Y9, Y4, Y4
	VPXOR	160(BX), Y8, Y9
	VPADDW	Y9, Y5, Y5
	VPXOR	192(BX), Y8, Y9
	VPADDW	Y9, Y6, Y6
	VPXOR	224(BX), Y8, Y9
	VPADDW	Y9, Y7, Y7
	ADDQ	$2, DX
	DECQ	CX
	JNZ	window0
store0:
	VMOVQ	R8, X8
	VPBROADCASTW	X8, Y8
	VPADDW	Y8, Y0, Y0
	VMOVDQU	Y0, 0(DI)
	VPADDW	Y8, Y1, Y1
	VMOVDQU	Y1, 32(DI)
	VPADDW	Y8, Y2, Y2
	VMOVDQU	Y2, 64(DI)
	VPADDW	Y8, Y3, Y3
	VMOVDQU	Y3, 96(DI)
	VPADDW	Y8, Y4, Y4
	VMOVDQU	Y4, 128(DI)
	VPADDW	Y8, Y5, Y5
	VMOVDQU	Y5, 160(DI)
	VPADDW	Y8, Y6, Y6
	VMOVDQU	Y6, 192(DI)
	VPADDW	Y8, Y7, Y7
	VMOVDQU	Y7, 224(DI)
	VPXOR	Y0, Y0, Y0
	VPXOR	Y1, Y1, Y1
	VPXOR	Y2, Y2, Y2
	VPXOR	Y3, Y3, Y3
	VPXOR	Y4, Y4, Y4
	VPXOR	Y5, Y5, Y5
	VPXOR	Y6, Y6, Y6
	VPXOR	Y7, Y7, Y7
	MOVQ	starts+16(FP), DX
	MOVQ	n+24(FP), CX
	XORQ	R8, R8
	TESTQ	CX, CX
	JZ	store1
window1:
	MOVWQZX	(DX), AX
	MOVQ	AX, BX
	SHRQ	$15, BX
	ADDQ	BX, R8
	NEGQ	BX
	VMOVQ	BX, X8
	VPBROADCASTQ	X8, Y8
	ANDQ	$0x1ff, AX
