	VPXOR	256(BX), Y8, Y9
	VPADDW	Y9, Y0, Y0
	VPXOR	288(BX), Y8, Y9
	VPADDW	Y9, Y1, Y1
	VPXOR	320(BX), Y8, Y9
	VPADDW	Y9, Y2, Y2
	VPXOR	352(BX), Y8, Y9
	VPADDW	Y9, Y3, Y3
	VPXOR	384(BX), Y8, Y9
	VPADDW	Y9, Y4, Y4
	VPXOR	416(BX), Y8, Y9
	VPADDW	Y9, Y5, Y5
	VPXOR	448(BX), Y8, Y9
	VPADDW	Y9, Y6, Y6
	VPXOR	480(BX), Y8, Y9
	VPADDW	Y9, Y7, Y7
